from pathlib import Path
import json,statistics,html,hashlib
R=Path(__file__).resolve().parent;ROOT=R.parent.parent
r=json.loads((R/'results.json').read_text());assert r['complete']
t={scope:{name:v['median_us'] for name,v in arms.items()} for scope,arms in r['times'].items()}
labels={'previous_triton':'이전 TriMul Triton + 동일 Transition','previous_h100':'이전 TriMul H100 + 동일 Transition','latest_candidate':'최신 TriMul 후보 + 동일 Transition'}
scopes={'inference':'추론','training_forward':'학습 forward','training':'학습 fwd+bwd'}
speeds={scope:{n:t[scope][n]/t[scope]['latest_candidate'] for n in ('previous_triton','previous_h100')} for scope in t}
telemetry={}
for scope in t:
 rows=[list(map(float,x['csv'].split(','))) for x in r['telemetry'] if x['phase']==scope and x['returncode']==0 and len(x['csv'].split(','))==5]
 telemetry[scope]={name:statistics.median(row[i] for row in rows) for i,name in enumerate(['sm_mhz','memory_mhz','power_w','power_limit_w','temperature_c'])}
latest_checks={scope:max(v['relative_l2'] for v in arms['latest_candidate'].values()) for scope,arms in r['checks'].items()}
mutation_max=max(v['relative_l2'] for cases in r['mutation'].values() for entries in cases.values() for v in entries.values())
trace=r['traces'];assert trace['training']['latest_candidate']['b1_fused']==1 and trace['training']['latest_candidate']['b7_joint']==1
assert any('DualBackwardSm90' in k for k in trace['training']['previous_h100'])
assert trace['inference']['latest_candidate']['infer_k3']==1
summary=dict(times_us=t,speedups=speeds,telemetry=telemetry,latest_cross_path_max_relative_l2=latest_checks,graph_eager_max_relative_l2=mutation_max,scope='one pair-only MiniPairformer block, L384, C128, B1',latest_training_diagnostic=True,transition_identical=True,production_dispatch_changed=False,job=r['job'])
(R/'summary.json').write_text(json.dumps(summary,indent=2))
lines=['# MiniPairformer 한 블록: 학습·추론 비교 · 2026-09-22','','**블록 구성 = 양방향 TriMul → Transition. 최신 조합 추론 %.3fms, 학습 fwd+bwd %.3fms.**'%(t['inference']['latest_candidate']/1000,t['training']['latest_candidate']/1000),'','## 동일 실행 비교','','| 모드 | 이전 TriMul Triton | 이전 TriMul H100 | 최신 TriMul 후보 | Triton 대비 | H100 대비 |','|---|---:|---:|---:|---:|---:|']
for scope,label in scopes.items():
 vals=t[scope];lines.append('| %s | %.3fms | %.3fms | **%.3fms** | %.2f배 | %.2f배 |'%(label,vals['previous_triton']/1000,vals['previous_h100']/1000,vals['latest_candidate']/1000,speeds[scope]['previous_triton'],speeds[scope]['previous_h100']))
lines+=['','## 측정 범위','','job%s, node01 H10080GB HBM3, B1/L384/C128, TriMul hidden128 per direction (packed256), Transition expansion4.'%r['job'],'pair-only MiniPairformerBlock과 같은 두 연산을 직접 연결한 커널 조합 벤치다. 16블록 스택·single track·triangle attention은 포함하지 않는다.','최신 수동 backward는 Transition의 실제 입력 gradient를 TriMul로 전달한다. 두 모듈의 따로 잰 시간을 더한 값이 아니다.','학습은 고정 row dropout25%, 추론은 dropout0 및 backward용 저장 없음. 두 residual과 합성 pair mask, live weight packing, 입력+15개 파라미터 gradient를 포함한다.','optimizer, dropout RNG 생성, compilation, CPU dispatch는 제외한다. static compile+manual CUDA graph, 모드마다5×250회 교차 측정.','Transition projection은 BF16, LN 파라미터는 FP32. squeeze는 nonzero 초기화하여 실제 branch와 gradients를 검사했다.','','## 비교 대상의 정확한 의미','','세 조합 모두 동일한 D128 Triton full-K/residual Transition과 동일 가중치를 쓴다. 바뀌는 것은 TriMul이다.','이전 TriMul은 보존된 Anthropic 도입 전 Triton/H100 경로와 기존 선택 config를 사용한다. 과거 전체 설치 환경 또는 옛 Transition 구현까지 재현한 비교는 아니다.','실제 profiler에서 이전 H100 FrontSingleWarpgroup/ParityF567/DualBackwardSm90, 최신 b1_fused/b7_joint를 확인했다.','추론 최신 경로는 infer_k1/infer_k3이며 학습 save_k3와 B7이 없다. 두 경로 모두 Transition kernel을 이어 실행한다.','최신 조합은 기본 MiniWorld 자동 dispatch로 승격한 상태가 아니다. 이전에 확인한 LN gradient 제한이 남아 있다.','','## 검증과 한계','','경로 간 비교는 기존 BF16 cross-algorithm 기준 forward0.5%, gradient1%를 사용했다. 이는 엄격한 동일 알고리즘 검증과 별개다.','최신 경로의 이전 Triton 대비 최대 상대L2: 학습 전체 %.6g, 학습 forward %.6g, 추론 %.6g.'%(latest_checks['training'],latest_checks['training_forward'],latest_checks['inference']), '새 입력/가중치 변형 후 graph/eager 비교에서는 LN gradient만5e-6 한도를 사용하고 나머지는 bit-exact를 요구했다. 실제 최대는%.6g다.'%mutation_max,'기존 LN 구현의 FP32 atomic 누산은 반복 실행에서 마지막 비트가 달라진다. job15566/15569는 이를 모두 bit-exact로 요구해 중단했고, 원래 LN 수치 한도를 사용한 최종 job에서 검증을 통과했다.','앞선 최신 TriMul 전체 검사에서 입력 LN gradient 최대9.535e-6 >5e-6였던 문제를 이 비교가 해결한 것은 아니다. **최신 학습 시간은 정확도 검증이 남은 후보의 진단값**이다.','Transition 및 일부 LN autotune cache miss는 타이밍 전에 heuristic24개 후보로 처리했다. 완전한 config-space 최적 튜닝을 했다는 주장은 아니다.','Transition은 모든 arm에서 같은 구현을 썼다. 런타임 autotuner가 best_config/cache를 노출하지 않아 해당 객체의 config 결과는 null/empty로 기록되었다.','반복 측정에 사용한 cubin/source·cache 환경을 이전 실행과 동일하다고 가정하지 않는다. 비율은 이번 실행 내부에서만 계산했다.','','## 재현·자료','','- [원본 결과 / 모든 시간표본 / kernel trace 목록](results.json)','- [요약과 telemetry](summary.json)','- [벤치 코드](bench.py)','- [이전 경로의 고정 config](pin_previous.py)','- [최신 TriMul 한계](../trimul_full_latest_20260922/README.md)','','저장소 루트에서 `sbatch --job-name=minipair-block runs/minipairformer_block_20260922/bench.sbatch`. 새 production 코드·기본 배선은 변경하지 않았다.']
(R/'README.md').write_text('\n'.join(lines)+'\n')
rows=''.join('<tr><td>%s</td><td>%.3f</td><td>%.3f</td><td><b>%.3f</b></td><td>%.2f×</td><td>%.2f×</td></tr>'%(label,t[scope]['previous_triton']/1000,t[scope]['previous_h100']/1000,t[scope]['latest_candidate']/1000,speeds[scope]['previous_triton'],speeds[scope]['previous_h100']) for scope,label in scopes.items())
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MiniPairformer 한 블록 비교</title><style>body{max-width:1100px;margin:24px auto;padding:0 16px;font:16px/1.65 system-ui;color:#24364c;background:#f3f6fa}section{background:white;padding:20px;margin:16px 0;border-radius:10px}.notice{background:#fff0d4;padding:14px;border-left:4px solid #bc7718}table{width:100%%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #d7e1eb;text-align:right}td:first-child,th:first-child{text-align:left}.scroll{overflow:auto}.flow{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.box{padding:15px;border:1px solid #82aeb4;background:#ecf8f2;border-radius:8px}a{color:#1765a4}</style><h1>MiniPairformer 한 블록 · 이전과 비교</h1><p>node01 H100 · B1/L384/C128 · pair-only · 학습dropout25%% / 추론dropout0</p><section><h2>전체를 직접 연결해 측정</h2><div class="flow"><div class="box">양방향 TriMul<br>이전 Triton / 이전 H100 / 최신 후보</div><b>→</b><div class="box">동일 D128 Transition<br>Triton full-K · residual fusion</div></div><p>Backward는 Transition → TriMul로 연결됩니다. 두 단독 시간의 합계가 아닙니다. 학습은 입력과15개 파라미터의 gradient를 포함합니다.</p></section><section><h2>동일 실행 결과 · ms</h2><div class="scroll"><table><tr><th>모드</th><th>이전 Triton</th><th>이전 H100</th><th>최신 후보</th><th>Triton 대비</th><th>H100 대비</th></tr>%s</table></div><p>모드마다5×250회 교차 CUDA graph. compile/CPU dispatch/optimizer/RNG 생성은 제외. 두 residual·pair mask 포함.</p></section><p class="notice"><b>최신 학습 시간은 진단 후보의 결과입니다.</b> 이전 전체 TriMul 검사에서 입력 LN gradient가 엄격 한도를 초과한 문제는 남아 있습니다. 기본 경로로 승격하지 않았습니다.</p><section><h2>비교 범위</h2><p>Transition을 동일하게 유지해 TriMul 변경이 전체 블록에 주는 효과를 측정했습니다. 과거 전체 설치 환경을 재현한 표가 아닙니다. 일부 cache miss는 측정 전에24개 후보를 탐색했으며 완전한 config tuning을 주장하지 않습니다.</p><p>추론 최신은 infer_k1/infer_k3, 학습 최신은 infer_k1/save_k3와b1_fused/b7_joint를 실제 trace에서 확인했습니다.</p></section><p><a href="README.md">구성·오차·재현·한계</a> · <a href="summary.json">요약</a> · <a href="results.json">원본 결과</a> · <a href="../../TRIMUL_STATUS.html">TriMul 현황</a></p></html>'''%rows
(R/'index.html').write_text(page)
print('SUMMARY',t,speeds)
